-- ==========================================================================
-- Pocket CRM — Complete Database Export (Structure & Seed Data)
-- Compatible with MySQL 5.7+, MySQL 8.0+, MariaDB & phpMyAdmin (Hostinger/cPanel)
-- Total Contacts: 86 | Includes Timeline Notes & Categorized Media Records
-- Generated: 05-09-2026
-- ==========================================================================

SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';
SET time_zone = '+00:00';

-- --------------------------------------------------------
-- Table structure for table `crm_contacts`
-- --------------------------------------------------------
DROP TABLE IF EXISTS `crm_contacts`;
CREATE TABLE `crm_contacts` (
  `id` VARCHAR(64) NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `phone` VARCHAR(50) DEFAULT NULL,
  `phone2` VARCHAR(50) DEFAULT NULL,
  `email` VARCHAR(255) DEFAULT NULL,
  `company` VARCHAR(255) DEFAULT NULL,
  `occupation` VARCHAR(255) DEFAULT 'Business Client',
  `category` ENUM('Lead', 'Client', 'Follow-up', 'Partner', 'Vendor', 'Contact') NOT NULL DEFAULT 'Lead',
  `address` TEXT DEFAULT NULL,
  `lead_from` VARCHAR(255) DEFAULT NULL,
  `notes` LONGTEXT DEFAULT NULL,
  `whatsapp_notes` LONGTEXT DEFAULT NULL,
  `drive_link` TEXT DEFAULT NULL,
  `website_link` TEXT DEFAULT NULL,
  `creds_server` TEXT DEFAULT NULL,
  `creds_social` TEXT DEFAULT NULL,
  `budget` VARCHAR(100) DEFAULT NULL,
  `amount_status` VARCHAR(100) DEFAULT 'Pending',
  `amount_percentage_paid` VARCHAR(50) DEFAULT '0',
  `specifications` LONGTEXT DEFAULT NULL,
  `is_starred` TINYINT(1) NOT NULL DEFAULT 0,
  `is_blocked` TINYINT(1) NOT NULL DEFAULT 0,
  `last_contact` VARCHAR(100) DEFAULT 'Recent',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  INDEX `idx_category` (`category`),
  INDEX `idx_phone` (`phone`),
  INDEX `idx_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- Table structure for table `crm_history`
-- --------------------------------------------------------
DROP TABLE IF EXISTS `crm_history`;
CREATE TABLE `crm_history` (
  `id` INT AUTO_INCREMENT NOT NULL,
  `contact_id` VARCHAR(64) NOT NULL,
  `staff` VARCHAR(100) DEFAULT 'Akash (Dev Lead)',
  `time_str` VARCHAR(100) DEFAULT 'Recent',
  `duration` VARCHAR(50) DEFAULT '15 mins',
  `type` ENUM('call', 'meet', 'chat', 'note', 'status') NOT NULL DEFAULT 'note',
  `note_text` LONGTEXT NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  INDEX `idx_contact_id` (`contact_id`),
  CONSTRAINT `fk_hist_contact` FOREIGN KEY (`contact_id`) REFERENCES `crm_contacts` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- Table structure for table `crm_media`
-- --------------------------------------------------------
DROP TABLE IF EXISTS `crm_media`;
CREATE TABLE `crm_media` (
  `id` INT AUTO_INCREMENT NOT NULL,
  `contact_id` VARCHAR(64) NOT NULL,
  `folder` ENUM('photos', 'documents', 'invoices', 'media') NOT NULL DEFAULT 'photos',
  `file_name` VARCHAR(255) DEFAULT NULL,
  `file_url` TEXT NOT NULL,
  `file_type` VARCHAR(50) DEFAULT 'image',
  `file_size` VARCHAR(50) DEFAULT NULL,
  `uploaded_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  INDEX `idx_media_contact` (`contact_id`),
  CONSTRAINT `fk_media_contact` FOREIGN KEY (`contact_id`) REFERENCES `crm_contacts` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- Table structure for table `crm_vault`
-- --------------------------------------------------------
DROP TABLE IF EXISTS `crm_vault`;
CREATE TABLE `crm_vault` (
  `id` INT AUTO_INCREMENT NOT NULL,
  `contact_id` VARCHAR(64) NOT NULL,
  `vault_type` ENUM('server', 'social', 'database', 'other') NOT NULL DEFAULT 'server',
  `label` VARCHAR(100) NOT NULL,
  `username` VARCHAR(255) DEFAULT NULL,
  `password_encrypted` TEXT DEFAULT NULL,
  `notes` TEXT DEFAULT NULL,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  INDEX `idx_vault_contact` (`contact_id`),
  CONSTRAINT `fk_vault_contact` FOREIGN KEY (`contact_id`) REFERENCES `crm_contacts` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- Dumping data for table `crm_contacts`
-- --------------------------------------------------------

-- --------------------------------------------------------
-- Dumping data for table `crm_media`
-- --------------------------------------------------------

SET FOREIGN_KEY_CHECKS = 1;

